const body = $('Webhook').item.json.body;
const brandItem = $('Lookup Brand Profile').all()[0];
const brand = brandItem ? brandItem.json : {};
const styleItem = $('Lookup Branch Style').all()[0];
const style = styleItem ? styleItem.json : {};
const primary = style.primary_color || '';
const secondary = style.secondary_color || '';
const accent = style.accent_color || '';

const brandName = brand.brand_name || body.branch || 'the brand';
const tone = body.tone || brand.default_tone || 'friendly';
const pron = brand.pronunciation_guide || '';
const aspect = body.aspect_ratio || '1:1';
const setting = body.setting || brand.default_setting || 'a clean, bright, on-brand backdrop';
const platform = body.platform || 'general';
const styleNotes = body.style_notes || '';
const message = body.message || '';
const segment = body.target_segment || 'general audience';
const referenceImageUrl = body.reference_image_url || '';
const referenceMode = (body.reference_mode === 'edit') ? 'edit' : 'inspire';
const revisionNotes = body.revision_notes || '';

const shape = { headline: 'short punchy headline, max 8 words', subtext: 'one supporting sentence, max 18 words', cta: '2-4 word call to action', caption: 'ready-to-publish social caption, 1-3 sentences, up to 3 hashtags' };

let copy_prompt = 'You are writing performance-marketing copy for a single static social ad. Brand: ' + brandName + '. Tone: ' + tone + '. Audience: ' + segment + '. Platform: ' + platform + '. Core message: ' + message + '. Pronunciation and brand rules: ' + pron + '. ' + (styleNotes ? ('Style notes: ' + styleNotes + '. ') : '') + 'Write the finished ad copy itself - never instructions, field descriptions or commentary. headline: short and punchy, max 8 words - this will be composited onto the image afterward by the app, not drawn by you. subtext: one supporting sentence, max 18 words. cta: 2-4 words. caption: ready-to-publish social caption, 1-3 sentences, up to 3 hashtags.';
if (revisionNotes) {
  copy_prompt += ' REVISION REQUEST - the previous attempt was rejected. Apply this feedback: ' + revisionNotes;
}

return [{ json: {
  copy_prompt,
  brand_name: brandName,
  tone,
  aspect_ratio: aspect,
  setting,
  platform,
  style_notes: styleNotes,
  message,
  job_id: body.job_id,
  branch: body.branch,
  reference_image_url: referenceImageUrl,
  reference_mode: referenceMode,
  revision_notes: revisionNotes,
  primary,
  secondary,
  accent,
} }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const prep = $('Prepare Copy Prompt').item.json;
const revisionNotes = prep.revision_notes || '';
const primary = prep.primary || '';
const secondary = prep.secondary || '';
const accent = prep.accent || '';

function extractJson(text) {
  try { return JSON.parse(text); } catch (e) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (e) {}
  }
  return null;
}

let copy = extractJson(raw);

// A 'headline' that is really schema/markdown junk is worse than no copy at
// all, because the app composites it onto the image afterward. Reject those outright.
const looksLikeJunk = (s) => !s
  || /`|\bmax \d+ words\b|\bcall to\b\s*$|^\s*[-*#]/i.test(s)
  || /^(headline|subtext|cta|caption)\b/i.test(s);

if (!copy || typeof copy !== 'object' || looksLikeJunk(copy.headline)) {
  // Fall back to the user's own words - they are always safe to show.
  const source = (prep.message || '').trim();
  const firstSentence = (source.split(/[.!?\n]/)[0] || prep.brand_name).trim();
  copy = {
    headline: firstSentence.split(/\s+/).slice(0, 8).join(' ') || prep.brand_name,
    subtext: source.slice(0, 140),
    cta: 'Learn More',
    caption: source.slice(0, 280) || (prep.brand_name + ' - new today.'),
  };
}

copy.headline = (copy.headline || prep.brand_name).toString();
copy.subtext = (copy.subtext || '').toString();
copy.cta = (copy.cta || 'Learn More').toString();
copy.caption = (copy.caption || copy.headline).toString();

const hasRef = !!(prep.reference_image_url);
const refMode = prep.reference_mode || 'inspire';

// Real brand hex colours from the branches table beat the generic brand-name
// phrasing whenever they exist - brand_profiles.brand_colors is always empty.
const colorParts = [
  primary ? ('primary ' + primary) : '',
  secondary ? ('secondary ' + secondary) : '',
  accent ? ('accent ' + accent) : '',
].filter(Boolean);
const colorPhrase = colorParts.length
  ? ('Brand colour palette to echo in the scene, props, wardrobe and colour grade: ' + colorParts.join(', ') + '. ')
  : ('Colour palette and visual style consistent with ' + prep.brand_name + '. ');

// The Trellis app composites the headline onto the image afterward in the
// real brand font, so the image itself must come back completely clean of
// text - no AI-drawn letters for the app to fight with or cover up.
const spaceRule = 'Compose with generous negative space in the lower third (uncluttered, low visual detail, gentle falloff) where headline text will be placed afterwards. Keep the main subject clear of that area. ';
const spaceRuleEdit = 'If needed, crop or extend the composition so the lower third has generous negative space (uncluttered, low visual detail) for headline text to be placed afterward. Keep the main subject clear of that area. ';
const strictNoText = 'CRITICAL: the image must contain NO text, NO words, NO letters, NO numbers, NO logos, NO watermarks, NO signage, NO captions of any kind. A completely text-free photograph.';
const editNoText = 'CRITICAL: do not ADD any text, words, letters, numbers, logos, watermarks, signage or captions to this photograph beyond what may already exist in it. Do not render the headline or any other text onto the image - the app composites the headline separately afterward.';

let image_prompt;
if (hasRef && refMode === 'edit') {
  image_prompt = 'The attached image is a real photograph. Edit THIS EXACT photograph into a finished marketing static advertisement. Preserve the authentic scene, people, objects and lighting exactly as photographed - do not replace, redraw or regenerate the scene. ' + spaceRuleEdit + 'You may apply only a subtle, tasteful colour grade consistent with ' + prep.brand_name + (colorParts.length ? (' and its brand colours (' + colorParts.join(', ') + ')') : '') + '. Output ' + prep.aspect_ratio + ' aspect ratio, cropping minimally if needed. ' + (prep.style_notes ? ('Style notes: ' + prep.style_notes + '. ') : '') + editNoText;
} else if (hasRef) {
  image_prompt = 'A reference photograph is attached. Use it ONLY as guidance for the setting, mood, lighting and composition - generate a NEW original marketing static advertisement image in the same spirit. ' + prep.aspect_ratio + ' aspect ratio composition. Setting: ' + prep.setting + '. ' + spaceRule + colorPhrase + prep.tone + ' tone, for ' + prep.platform + '. ' + (prep.style_notes ? ('Style notes: ' + prep.style_notes + '. ') : '') + strictNoText;
} else {
  image_prompt = 'A single professional marketing static advertisement image. ' + prep.aspect_ratio + ' aspect ratio composition. Setting: ' + prep.setting + '. ' + spaceRule + colorPhrase + prep.tone + ' tone, for ' + prep.platform + '. ' + (prep.style_notes ? ('Style notes: ' + prep.style_notes + '. ') : '') + strictNoText;
}

if (revisionNotes) {
  image_prompt += ' REVISION REQUEST - the previous attempt was rejected. Apply this feedback: ' + revisionNotes;
}

return [{ json: {
  headline: copy.headline,
  subtext: copy.subtext,
  cta: copy.cta,
  caption: copy.caption,
  image_prompt,
  job_id: prep.job_id,
  branch: prep.branch,
  aspect_ratio: prep.aspect_ratio,
  reference_image_url: prep.reference_image_url || '',
  reference_mode: refMode,
  revision_notes: revisionNotes,
  primary,
  secondary,
  accent,
} }];

const attempt = $runIndex + 1;
const prep = $('Parse Copy').item.json;
return [{ json: {
  attempt,
  image_prompt: prep.image_prompt,
  job_id: prep.job_id,
  branch: prep.branch,
  aspect_ratio: prep.aspect_ratio,
  reference_image_url: prep.reference_image_url || '',
  reference_mode: prep.reference_mode || 'inspire',
  revision_notes: prep.revision_notes || '',
  primary: prep.primary || '',
  secondary: prep.secondary || '',
  accent: prep.accent || '',
} }];

const cands = $json.candidates || [];
let b64 = null;
let mime = 'image/png';

for (const c of cands) {
  const parts = (c.content && c.content.parts) || [];
  for (const p of parts) {
    const inline = p.inlineData || p.inline_data;
    if (inline && inline.data) {
      b64 = inline.data;
      mime = inline.mimeType || inline.mime_type || mime;
      break;
    }
  }
  if (b64) break;
}

if (!b64) {
  throw new Error('No image returned by Gemini. Raw: ' + JSON.stringify($json).slice(0, 400));
}

const jobId = $('Parse Copy').item.json.job_id;
const attempt = $('Track Frame Attempt').item.json.attempt;
const ext = mime.includes('jpeg') ? 'jpg' : 'png';
const rand = Math.random().toString(36).slice(2, 8);
const path = 'static-ads/' + jobId + '/ad-' + attempt + '-' + rand + '.' + ext;

return [{
  json: { storage_path: path, mime, attempt, base64: b64 },
  binary: {
    data: {
      data: b64,
      mimeType: mime,
      fileName: 'ad-' + attempt + '-' + rand + '.' + ext,
    },
  },
}];

const text = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const passed = /^\s*yes/i.test(text);
return [{ json: { passed, reason: text.slice(0, 300) } }];

const prep = $('Track Frame Attempt').item.json;
const binary = $input.item.binary && $input.item.binary.data;
if (!binary) { throw new Error('Reference image fetch returned no binary data'); }
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = binary.mimeType && binary.mimeType.startsWith('image/') ? binary.mimeType : 'image/jpeg';
return [{ json: Object.assign({}, prep, { ref_base64: buf.toString('base64'), ref_mime: mime }) }];
